  "commands": [
    {
      "keystrokes": "cat << 'EOF' > get_stats.py
import pandas as pd
import numpy as np

def clean_value(val):
    if pd.isna(val):
        return np.nan
    if isinstance(val, str):
        val = val.replace(',', '.')
        try:
            return float(val)
        except ValueError:
            return np.nan
    return float(val)

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')
df = df.dropna()
for col in df.columns:
    if col != 'patient_id':
        df[col] = df[col].apply(clean_value)
df = df.dropna()

stats = df.describe(percentiles=[0.05, 0.95]).transpose()
print(stats[['min', '5%', '95%', 'max']].to_string())
EOF
python3 get_stats.py > column_ranges.txt
cat column_ranges.txt
",
      "duration": 2.0
    }
  ]
}

